import{c as a,Q as e,j as s,m as d}from"./chunks/framework.DOi4mjdC.js";const n="/assets/%E6%B5%81%E6%B0%B4%E7%BA%BF%E7%AD%89%E5%BE%85%E7%A4%BA%E6%84%8F%E5%9B%BE.CVdBX088.png",h=JSON.parse('{"title":"LocalMemBar","description":"","frontmatter":{},"headers":[{"level":1,"title":"LocalMemBar","slug":"localmembar"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Reg矢量计算/同步控制/LocalMemBar.md","filePath":"api/SIMD-API/基础API/Reg矢量计算/同步控制/LocalMemBar.md"}'),r={name:"api/SIMD-API/基础API/Reg矢量计算/同步控制/LocalMemBar.md"};function l(p,t,i,o,c,A){return e(),s("div",null,[...t[0]||(t[0]=[d('<h1 id="localmembar" tabindex="-1">LocalMemBar <a class="header-anchor" href="#localmembar" aria-label="Permalink to &quot;LocalMemBar&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>Reg矢量计算宏函数内不同流水线之间的同步指令。该同步指令指定src源流水线和dst目的流水线，如下图所示，目的流水线将等待源流水线上所有指令完成才进行执行。读写场景下，当读指令使用的寄存器和写指令使用的寄存器相同时，可以触发寄存器保序，指令将会按照代码顺序执行，不需要插入同步指令，而当使用的寄存器不同时，如果要确保读写指令顺序执行，则需要插入同步指令，写写场景同理。</p><p><strong>图 1</strong> 流水线等待示意图<br><img src="'+n+`" alt="" title="流水线等待示意图"></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;MemType src, MemType dst&gt; </span></span>
<span class="line"><span>__simd_callee__ inline void LocalMemBar()</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>src</td><td>源流水线，类型为MemType，具体参见表2 MemType取值说明。</td></tr><tr><td>dst</td><td>目的流水线，类型为MemType，具体参见表2 MemType取值说明。</td></tr></tbody></table><p><strong>表 2</strong> MemType取值说明</p><table tabindex="0"><thead><tr><th>MemType取值</th><th>含义</th></tr></thead><tbody><tr><td>VEC_STORE</td><td>SIMD_VF函数内矢量写UB流水线。 对应寄存器到UB的搬运指令，如StoreAlign、StoreUnAlign、Store。</td></tr><tr><td>VEC_LOAD</td><td>SIMD_VF函数内矢量读UB流水线。 对应UB到寄存器的搬运指令，如LoadAlign、LoadUnAlign、Load。</td></tr><tr><td>SCALAR_STORE</td><td>SIMD_VF函数内标量写UB流水线。 对应标量写入UB的指令，如Duplicate。</td></tr><tr><td>SCALAR_LOAD</td><td>SIMD_VF函数内标量读UB流水线。 对应UB读取标量的指令，如GetValue。</td></tr><tr><td>VEC_ALL</td><td>SIMD_VF函数内所有矢量读写UB流水线。</td></tr><tr><td>SCALAR_ALL</td><td>SIMD_VF函数内所有标量读写UB流水线。</td></tr></tbody></table><p><strong>表 3</strong> src和dst组合取值说明</p><table tabindex="0"><thead><tr><th>src</th><th>dst</th></tr></thead><tbody><tr><td>VEC_STORE</td><td>VEC_LOAD</td></tr><tr><td>VEC_LOAD</td><td>VEC_STORE</td></tr><tr><td>VEC_STORE</td><td>VEC_STORE</td></tr><tr><td>VEC_STORE</td><td>SCALAR_LOAD</td></tr><tr><td>VEC_STORE</td><td>SCALAR_STORE</td></tr><tr><td>VEC_LOAD</td><td>SCALAR_STORE</td></tr><tr><td>SCALAR_STORE</td><td>VEC_LOAD</td></tr><tr><td>SCALAR_STORE</td><td>VEC_STORE</td></tr><tr><td>SCALAR_LOAD</td><td>VEC_STORE</td></tr><tr><td>VEC_ALL</td><td>VEC_ALL</td></tr><tr><td>VEC_ALL</td><td>SCALAR_ALL</td></tr><tr><td>SCALAR_ALL</td><td>VEC_ALL</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>如下示例中dstPtr和src0Ptr为同一个UB地址，for循环的第二次迭代中读UB矢量搬运和第一次迭代中写UB矢量搬运操作了同一块UB地址空间，因此第二次循环中读UB矢量搬运需要等待第一次循环中写UB矢量搬运执行完成后才能执行，需要插入VEC_LOAD等待VEC_STORE的同步。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename T&gt;</span></span>
<span class="line"><span>__simd_vf__ inline void AddVF(__ubuf__ T* dstAddr, __ubuf__ T* src0Addr, __ubuf__ T* src1Addr, uint32_t count, uint32_t oneRepeatSize, uint16_t repeatTimes)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; srcReg0;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; srcReg1;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; dstReg;</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg mask;   </span></span>
<span class="line"><span>    for (uint16_t i = 0; i &lt; repeatTimes; i++) {</span></span>
<span class="line"><span>        mask = AscendC::Reg::UpdateMask&lt;T&gt;(count);</span></span>
<span class="line"><span>        AscendC::Reg::LocalMemBar&lt;AscendC::Reg::MemType::VEC_STORE, AscendC::Reg::MemType::VEC_LOAD&gt;();</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg0, src0Addr);</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign(srcReg1, src1Addr + i * oneRepeatSize);</span></span>
<span class="line"><span>        AscendC::Reg::Add(dstReg, srcReg0, srcReg1, mask);</span></span>
<span class="line"><span>        AscendC::Reg::StoreAlign(dstAddr, dstReg, mask);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,22)])])}const g=a(r,[["render",l]]);export{h as __pageData,g as default};
